arguments.file_text:
@typeparam TItem

@if (Items is null || Items.Count == 0)
{
    @if (EmptyTemplate is not null)
    {
        @EmptyTemplate
    }
    else
    {
        <p>No items to display.</p>
    }
}
else
{
    <table>
        <thead>
            <tr>@HeaderTemplate</tr>
        </thead>
        <tbody>
            @foreach (var item in Items)
            {
                <tr @key="item" @onclick="() => HandleRowClick(item)">
                    @RowTemplate!(item)
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter, EditorRequired] public IReadOnlyList<TItem> Items { get; set; } = default!;
    [Parameter, EditorRequired] public RenderFragment? HeaderTemplate { get; set; }
    [Parameter, EditorRequired] public RenderFragment<TItem>? RowTemplate { get; set; }
    [Parameter] public RenderFragment? EmptyTemplate { get; set; }
    [Parameter] public EventCallback<TItem> OnRowClick { get; set; }

    private async Task HandleRowClick(TItem item)
    {
        if (OnRowClick.HasDelegate)
        {
            await OnRowClick.InvokeAsync(item);
        }
    }
}

